Rules.InvariantScript:
40 + 320 + With(
  {
    t: 2 * Pi() * sldHypSmall.Value * ctxHypN / 600,
    q: (sldHypBig.Value - sldHypSmall.Value) / sldHypSmall.Value,
    s: 290 / (sldHypBig.Value - sldHypSmall.Value + sldHypDist.Value)
  },
  s * ((sldHypBig.Value - sldHypSmall.Value) * Cos(t) + sldHypDist.Value * Cos(q * t))
) - Self.Width / 2

88 + 320 + With(
  {
    t: 2 * Pi() * sldHypSmall.Value * ctxHypN / 600,
    q: (sldHypBig.Value - sldHypSmall.Value) / sldHypSmall.Value,
    s: 290 / (sldHypBig.Value - sldHypSmall.Value + sldHypDist.Value)
  },
  s * ((sldHypBig.Value - sldHypSmall.Value) * Sin(t) - sldHypDist.Value * Sin(q * t))
) - Self.Height / 2
